const students = [{ id: 1, name: "小雨" }, { id: 2, name: "小林" }];
const courses = [{ id: 10, title: "数据库入门" }, { id: 20, title: "JavaScript" }];
const enrollments = [];

// 1. INSERT：小陈加入 students 表。
students.push({ id: 3, name: "小陈" });

// 2. INSERT：小陈报名数据库入门。
// 报名记录只保存两个编号，不重复保存姓名和课程标题。
enrollments.push({ studentId: 3, courseId: 10, status: "刚报名" });

// 3. JOIN：把编号换回人能读懂的名称。
const result = enrollments.map((enrollment) => {
  const student = students.find((item) => item.id === enrollment.studentId);
  const course = courses.find((item) => item.id === enrollment.courseId);
  return { student: student.name, course: course.title, status: enrollment.status };
});

console.log("课程报名结果:", result);
